"""Separate visual reread difference from conservative radius and systematic bias."""
from pathlib import Path
import json,math,sys,hashlib
annotation,out=map(Path,sys.argv[1:]);d=json.loads(annotation.read_text());frames=d['frames'];base=frames[0]['points'];rows=[]
for f in frames[1:]:
 for key,p in f['points'].items():
  a=base[key];rows.append({'frame':f['frame'],'point':key,'group':'head' if key in ['nose','left_eye','right_eye'] else 'forepaw','displacement_px':math.dist(p['xy'],a['xy']),'conservative_radius_sum_px':p['conservative_radius_px']+a['conservative_radius_px'],'visible':p['visibility']=='visible' and a['visibility']=='visible'})
summary={'scope':'source-only, before new output; five fixed frames and five fixed visible proxies','level_A':'OBSERVABLE_SCREEN_CHANGE; exploratory GO subject to independent input/safety contract','level_B':'INCONCLUSIVE; absolute movement not proof of articulation','level_C':'NOT_RUN','annotation_sha256':hashlib.sha256(annotation.read_bytes()).hexdigest(),'same_agent_reread_not_ground_truth':True,'systematic_bias':'UNKNOWN','radius_kind':'conservative heuristic radius, not trackerRMSE/stddev/95percentCI','old_B010_E_copy_px':15.510671754361123,'old_B010_radius_sum_mean_px':19.422222222222224,'current_E_copy_px':sum(x['displacement_px'] for x in rows)/len(rows),'current_radius_sum_mean_px':sum(x['conservative_radius_sum_px'] for x in rows)/len(rows),'coverage':{'visible':sum(x['visible'] for x in rows),'expected':20},'groups':{},'gain':'UNDEFINED for B011 integrated gain; fixed before generation, not a generation gate','temporal_quality':'UNVERIFIED','new_output':'NOT_RUN'}
for name in ['head','forepaw']:
 group=[x for x in rows if x['group']==name];diffs=[p['reread_difference_px'] for f in frames for k,p in f['points'].items() if ('head' if k in ['nose','left_eye','right_eye'] else 'forepaw')==name]
 summary['groups'][name]={'n_displacements':len(group),'mean_displacement_px':sum(x['displacement_px'] for x in group)/len(group),'mean_radius_sum_px':sum(x['conservative_radius_sum_px'] for x in group)/len(group),'above_radius_count':sum(x['displacement_px']>x['conservative_radius_sum_px'] for x in group),'same_agent_reread_difference_mean_px':sum(diffs)/len(diffs),'same_agent_reread_difference_max_px':max(diffs),'reread_not_independent_accuracy_measurement':True}
out.mkdir(parents=True,exist_ok=True);(out/'observation-summary.json').write_text(json.dumps(summary,indent=2)+'\n');(out/'displacements-private.json').write_text(json.dumps(rows,indent=2)+'\n');print(json.dumps(summary,indent=2))
